function telegramChunks(raw, limit = 3500) {
  const escape = value => value.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const text = String(raw ?? '').replace(/<br\s*\/?\s*>/gi, '\n').replace(/<\/?(?:p|div)>/gi, '\n').replace(/<\/?span[^>]*>/gi, '');
