  if (!Number.isInteger(age) || age < 10 || age > 120) return reject('Укажите корректный возраст');
  if (!Number.isFinite(height) || height < 100 || height > 250) return reject('Укажите рост от 100 до 250 см');
  if (!Number.isFinite(weight) || weight < 30 || weight > 300) return reject('Укажите вес от 30 до 300 кг');
  if (![1.2, 1.375, 1.55, 1.725, 1.9].includes(activity)) return reject('Выберите уровень активности');
  if (!['male', 'female'].includes(body.gender)) return reject('Выберите пол');
  if (!['lose', 'lose_fast', 'maintain', 'gain', 'gain_fast'].includes(body.goal)) return reject('Выберите цель');
